#endif /* (!VX1000_COMPILED_FOR_SLAVECORES) && (VX1000_MAILBOX && (VX1000_MAILBOX_OVERLAY_CONTROL || VX1000_MAILBOX_FLASH || VX1000_MAILBOX_CAL_READ_WRITE)) */

